const inputText = $input.first().json.text;

// Improved regex to capture find() and findOne() queries along with optional projection
const match = inputText.match(/(?:find|findOne)\s*\(\s*([\s\S]*?)\s*(?:,\s*([\s\S]*?))?\s*\)/);

if (match && match[1]) {
  try {
    const queryString = match[1].trim();
    const projectionString = match[2] ? match[2].trim() : "{}";

    // Convert MongoDB-style object notation to valid JSON format
    const sanitizedQuery = queryString.replace(/(\w+):/g, '"$1":');
    const sanitizedProjection = projectionString.replace(/(\w+):/g, '"$1":');

    // Parse JSON safely
    const extractedQuery = JSON.parse(sanitizedQuery);
    const extractedProjection = JSON.parse(sanitizedProjection);

    return [{ query: extractedQuery, projection: extractedProjection }];
  } catch (error) {
    return [{ error: `Invalid JSON format in query or projection: ${error.message}` }];
  }
} else {
  return [{ error: "No valid query found" }];
}

const inputText = $input.first().json.text;

// Extract the aggregation pipeline inside aggregate([...])
const match = inputText.match(/\.aggregate\s*\(\s*(\[[\s\S]*\])\s*\)/);

if (match && match[1]) {
  try {
    let extractedPipeline = match[1];

    // Convert ISODate("...") to valid JavaScript Date
    extractedPipeline = extractedPipeline.replace(/ISODate\s*\(\s*"(.*?)"\s*\)/g, 'new Date("$1")');

    // Convert MongoDB extended JSON (unquoted keys) into valid JSON format
    extractedPipeline = extractedPipeline.replace(/([{,]\s*)([$\w]+)\s*:/g, '$1"$2":');

    // Parse JSON safely
    const parsedPipeline = Function('"use strict"; return (' + extractedPipeline + ')')();

    return [{ pipeline: parsedPipeline }];
  } catch (error) {
    return [{ error: "Invalid JSON format in aggregation pipeline", details: error.message }];
  }
} else {
  return [{ error: "No valid aggregation pipeline found" }];
}

// Get input data
const inputData = $input.first().json;

// Get today's date
const today = new Date();
const formattedDate = today.toISOString().split('T')[0];

// Return the combined result
return [
  {
    json: {
      body: inputData.body,
      today: formattedDate
    }
  }
];
